from pathlib import Path
import csv
import difflib
import hashlib
import json
import statistics
import struct
import subprocess
import zipfile

root = Path.cwd()
evidence = root / "build" / "stage3a-evidence"


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def text(path):
    data = path.read_bytes()
    encoding = "utf-16" if data[:2] in (b"\xff\xfe", b"\xfe\xff") else "utf-8-sig"
    return data.decode(encoding)


def artifact(path):
    return {"path": str(path.relative_to(root)), "sha256": digest(path), "text": text(path)}


def load(path):
    return json.loads(text(path))


def pe_sections(path):
    data = path.read_bytes()
    pe = struct.unpack_from("<I", data, 0x3c)[0]
    assert data[pe:pe + 4] == b"PE\0\0", path
    count = struct.unpack_from("<H", data, pe + 6)[0]
    optional_size = struct.unpack_from("<H", data, pe + 20)[0]
    result = {}
    for index in range(count):
        header = pe + 24 + optional_size + 40 * index
        name = data[header:header + 8].rstrip(b"\0").decode("ascii")
        size, offset = struct.unpack_from("<II", data, header + 16)
        result[name] = {"raw_size": size, "sha256": hashlib.sha256(data[offset:offset + size]).hexdigest()}
    return result


def distribution(values):
    ordered = sorted(values)
    return {
        "samples": values,
        "minimum": ordered[0],
        "median": statistics.median(values),
        "maximum": ordered[-1],
        "mean": statistics.mean(values),
        "sample_stdev": statistics.stdev(values) if len(values) > 1 else 0,
    }


phases = ("scroll-sync", "selection-publication", "source-publication", "paint-visible-rows")


def comparison_statistics(records):
    def value(record, phase, metric):
        p = next(p for p in record["Phases"] if p["phase"] == phase)
        if metric in ("kernel_cpu_ms", "user_cpu_ms"):
            prefix = metric.split("_")[0]
            return (p[f"{prefix}_after100ns"] - p[f"{prefix}_before100ns"]) / 10000.0
        return p[metric]

    result = {}
    for phase in phases:
        result[phase] = {}
        for metric in ("wall_ms", "ui_thread_cpu_ms", "kernel_cpu_ms", "user_cpu_ms", "cpp_allocations"):
            groups = {
                revision: [
                    value(record, phase, metric)
                    for record in records
                    if record["Kind"] == "recorded" and record["Revision"] == revision
                ]
                for revision in ("baseline", "candidate")
            }
            if not all(groups.values()):
                continue
            baseline = statistics.median(groups["baseline"])
            candidate = statistics.median(groups["candidate"])
            paired = [b - a for a, b in zip(groups["baseline"], groups["candidate"])]
            ratios = [(b / a - 1) * 100 if a else None
                      for a, b in zip(groups["baseline"], groups["candidate"])]
            result[phase][metric] = {
                **{revision: distribution(values) for revision, values in groups.items()},
                "median_absolute_delta": candidate - baseline,
                "median_relative_percent": (candidate / baseline - 1) * 100 if baseline else None,
                "paired_deltas": paired,
                "paired_relative_percents": ratios,
                "paired_median_relative_percent": statistics.median([r for r in ratios if r is not None])
                if any(r is not None for r in ratios) else None,
                "candidate_slower_pairs": sum(delta > 0 for delta in paired),
            }
    return result


comparison = evidence / "host-comparison-final4"
records = load(comparison / "samples.json") if (comparison / "samples.json").is_file() else []
statistics_output = comparison_statistics(records)

selected = [
    p for p in evidence.iterdir()
    if p.is_file() and p.suffix in (".log", ".json", ".txt", ".csv", ".rsp")
    and (
        p.name.startswith(("baseline-", "candidate-", "final-", "final3-", "final4-", "collection-diagnostic",
                           "state-diagnostic", "retirement-negative", "probe-negative",
                           "thumbnail-", "runner-validation", "validate-runner", "parent-"))
    )
]
selected += [evidence / "storage-probe.cpp", evidence / "collections-window-diagnostic.cpp",
