selected += [p for p in comparison.rglob("*") if p.suffix in (".log", ".rsp", ".csv", ".json")]
additional_blocks = {}
for name in ("host-comparison-final", "cycle-diagnostic", "host-comparison-extended",
             "host-comparison-fixed", "host-comparison-hover-controlled", "host-comparison-hover-extended",
