    if name == "host-comparison-extended":
        for record in additional_blocks[name]["records"]:
            record["Regime"] = (
                "pre-normal-warmup" if record["Kind"] == "warmup" else
                "pre-normal" if record["Round"] < 4 else
                "pre-transition" if record["Round"] == 4 or
                (record["Round"] == 5 and record["Revision"] == "baseline") else
                "interrupted" if record["Round"] == 5 else "post"
            )
        additional_blocks[name]["post_gap_descriptive_only_statistics"] = comparison_statistics(
            [record for record in additional_blocks[name]["records"] if record["Regime"] == "post"])
    selected += [p for p in directory.rglob("*") if p.suffix in (".log", ".rsp", ".csv", ".json", ".cpp")]
for name in ("thumbnail-lifetime", "runner-validation"):
