inline void stage3a_diagnostic(HWND hwnd, const char* phase, LRESULT observed = -1) {
    if (observed == -1) observed = SendMessageW(hwnd, WM_APP + 60, 14, 0);
    std::cout << "stage3a phase=" << phase << " pid=" << GetCurrentProcessId()
        << " thread=" << GetCurrentThreadId() << " peers=" << observed
        << " popups=" << SendMessageW(hwnd, WM_APP + 60, 24, 0) << std::endl;
    if (observed == 8) return;
    EnumChildWindows(hwnd, [](HWND child, LPARAM) -> BOOL {
        wchar_t name[256]{}, type[128]{};
        GetWindowTextW(child, name, 256); GetClassNameW(child, type, 128);
        std::wcout << L"  child=" << child << L" parent=" << GetParent(child)
            << L" id=" << GetDlgCtrlID(child) << L" visible=" << IsWindowVisible(child)
            << L" enabled=" << IsWindowEnabled(child) << L" class=" << type << L" name=" << name << std::endl;
        return TRUE;
    }, 0);
}

