#include <cstdlib>
#include <iostream>
#include <new>
namespace {
bool recording{};
std::size_t sizes[32]{}, count{}, total{};
}
void* operator new(std::size_t size) {
    if (recording) {
        if (count < 32) sizes[count] = size;
        ++count; total += size;
    }
    if (auto* memory = std::malloc(size ? size : 1)) return memory;
    throw std::bad_alloc{};
}
void* operator new[](std::size_t size) { return ::operator new(size); }
void operator delete(void* value) noexcept { std::free(value); }
void operator delete[](void* value) noexcept { std::free(value); }
void operator delete(void* value, std::size_t) noexcept { std::free(value); }
void operator delete[](void* value, std::size_t) noexcept { std::free(value); }
template<class State> void state(const char* name) {
    count = total = 0;
    recording = true;
    auto value = std::make_shared<State>();
    recording = false;
    std::cout << name << " sizeof=" << sizeof(State) << " allocations=" << count
        << " requested_bytes=" << total << " allocation_sizes=";
    for (std::size_t index = 0; index < count && index < 32; ++index) std::cout << sizes[index] << ',';
    std::cout << '\n';
}
int main() {
    state<xui::ControlAccessibility>("ControlAccessibility");
    state<xui::AccessibilityState>("LegacyAccessibility");
#ifdef STAGE3A_CANDIDATE
    state<xui::CollectionAccessibility>("CollectionAccessibility");
    state<xui::GridAccessibility>("GridAccessibility");
    std::cout << "HostPeer=" << sizeof(xui::HostPeer)
        << " CollectionHostPeer=" << sizeof(xui::CollectionHostPeer)
        << " GridHostPeer=" << sizeof(xui::GridHostPeer)
        << " FileListHostPeer=" << sizeof(xui::FileListHostPeer) << '\n';
#endif
    std::cout << "ControlSnapshot=" << sizeof(xui::ControlSnapshot)
        << " ListPeer=" << sizeof(xui::ListPeer) << '\n';
}

