$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$evidence = Join-Path $root 'build\stage3a-evidence'
$sample = @(Get-Content "$evidence\host-comparison-final\samples.json" -Raw | ConvertFrom-Json)[0]
$global:Stage3aRunnerFixture = @(Get-Content $sample.Stdout)
$global:Stage3aRunnerStarted = 0
$global:Stage3aRunnerInvalidate = $false
$global:Stage3aRunnerOverBudget = $false
function Start-Process {
    param($FilePath, [switch]$PassThru, $RedirectStandardOutput, $RedirectStandardError)
    ++$global:Stage3aRunnerStarted
    $phases = @($global:Stage3aRunnerFixture | ConvertFrom-Json)
    if ($global:Stage3aRunnerInvalidate -and $global:Stage3aRunnerStarted -eq 4) {
        ++$phases[0].item_reads
    }
    $phases | ForEach-Object { $_ | ConvertTo-Json -Depth 8 -Compress } |
        Set-Content $RedirectStandardOutput
    Set-Content $RedirectStandardError ''
    if ($global:Stage3aRunnerOverBudget) {
        $clock = [pscustomobject]@{ Elapsed = [TimeSpan]::FromMilliseconds(90001) }
        $clock | Add-Member ScriptMethod Stop {}
        Set-Variable -Name clock -Value $clock -Scope 1
    }
    $process = [pscustomobject]@{ ExitCode = 0; TotalProcessorTime = [TimeSpan]::FromSeconds(1) }
    $process | Add-Member ScriptMethod WaitForExit { param($timeout) return $true }
    $process | Add-Member ScriptMethod Refresh {}
    return $process
}
$results = @()
foreach ($case in @('valid', 'mismatched-work', 'elapsed-budget')) {
    $directory = Join-Path $evidence "runner-validation\$case"
    foreach ($revision in @('baseline', 'candidate')) {
        New-Item -ItemType Directory -Force "$directory\$revision" | Out-Null
        Copy-Item "$evidence\host-comparison-fixed\$revision\collection_host_probe.exe" "$directory\$revision"
    }
    $global:Stage3aRunnerStarted = 0
    $global:Stage3aRunnerInvalidate = $case -eq 'mismatched-work'
    $global:Stage3aRunnerOverBudget = $case -eq 'elapsed-budget'
    $failure = $null
    try {
        & "$root\tests\collection-host-evidence.ps1" -Mode Measure `
            -BaselineSource build\stage3a-baseline-source `
            -BaselineBuild build\stage3a-baseline-final -CandidateBuild build\stage3a-candidate-final3 `
            -EvidenceDirectory $directory -Warmups 2 -Samples 7
    } catch {
        $failure = $_.ToString()
    }
    if (!(Test-Path "$directory\samples.json")) {
        throw "Runner unexpectedly failed before recording: $failure"
    }
    $records = @(Get-Content "$directory\samples.json" -Raw | ConvertFrom-Json)
    if ($case -eq 'valid') {
        if ($failure -or $records.Count -ne 18 -or $global:Stage3aRunnerStarted -ne 18) {
            throw "Valid synthetic runner control failed: $failure"
        }
    } elseif ($case -eq 'mismatched-work' -and ($failure -notlike 'Actual scroll-sync item_reads work changed*' -or
        $global:Stage3aRunnerStarted -ne 4 -or $records.Count -ne 4)) {
        throw "Mismatched-work synthetic control did not fail immediately: $failure"
    } elseif ($case -eq 'elapsed-budget' -and ($failure -notlike 'Probe exceeded its 90-second elapsed budget*' -or
        $global:Stage3aRunnerStarted -ne 1 -or $records.Count -ne 1 -or !$records[0].ExceededWallBudget)) {
        throw "Elapsed-budget synthetic control did not fail immediately: $failure"
    }
    foreach ($record in $records) {
        if (!$record.StartedUtc -or !$record.CompletedUtc -or $record.Phases.Count -ne 5) {
            throw 'Synthetic runner record lost UTC endpoints or parsed raw phases'
        }
    }
    $results += [pscustomobject]@{
        Case = $case; Synthetic = $true; ProcessesSimulated = $global:Stage3aRunnerStarted
        RecordsRetained = $records.Count; ExpectedFailure = $failure
    }
}
$results | ConvertTo-Json | Set-Content "$evidence\runner-validation\result.json"
Write-Host 'Runner synthetic controls passed: valid18, immediate mismatched-work rejection4 and elapsed-budget rejection1, UTC/raw data retained'
